return $input.all().map(item => ({ json: { ...item.json, config } }));

// PROVISIONAL / TO_VALIDATE: placeholder extraction logic only — a guess at
// Fresha's email format. Rebuild against a real Fresha booking-confirmation
// email (see config/fresha-email-fixture.example.txt, which is FICTIONAL,
// not real) before trusting this node. Fails safely: parseOk=false routes to
// the NEEDS_HUMAN_REVIEW branch instead of guessing.
const item = $input.item.json;
const config = item.config;
const body = item.text || item.html || '';
const subject = item.subject || '';

const clientNameMatch = body.match(/(?:Client|Customer|Booked by)[:\s]+([A-Za-z '-]+)/i);
const serviceMatch = body.match(/(?:Service|Appointment)[:\s]+([A-Za-z0-9 ,'-]+)/i);
const dateMatch = body.match(/(?:Date|When)[:\s]+(\d{4}-\d{2}-\d{2})/i);
const timeMatch = body.match(/(\d{1,2}:\d{2})/);
const refMatch = body.match(/(?:Booking (?:ref|reference|id))[:\s#]+([A-Za-z0-9-]+)/i);

const clientName = clientNameMatch ? clientNameMatch[1].trim() : null;
const service = serviceMatch ? serviceMatch[1].trim() : null;
const bookingDate = dateMatch ? dateMatch[1].trim() : null;
const bookingTime = timeMatch ? timeMatch[1].trim() : null;
const bookingRef = refMatch ? refMatch[1].trim() : null;

const parseOk = Boolean(clientName && service && bookingDate && bookingTime);

return [{
  json: {
    config,
    clientName,
    service,
    bookingDate,
    bookingTime,
    bookingRef: bookingRef || `NOREF-${Date.now()}`,
    subject,
    parseOk,
    source: 'email'
  }
}];

