// TO_VALIDATE: reminder_escalation_hours / reminder_resend_cooldown_hours are
// placeholders — see config/mehua-config.json. Escalates status to OVERDUE
// only after the escalation window; never auto-verifies or auto-cancels.
const configItem = $('Load Mehua Config (Overdue Path)').first().json.config;
const escalationHours = configItem.reminder_escalation_hours;
const cooldownHours = configItem.reminder_resend_cooldown_hours;
const now = new Date();

const dueForReminder = $input.all().filter(item => {
  const status = item.json['Status'];
  const sentAt = item.json['Deposit Request Sent At'];
  const lastReminderAt = item.json['Reminder Sent At'];
  if (!sentAt) return false;
  if (status !== 'AWAITING_DEPOSIT' && status !== 'OVERDUE') return false;
  const hoursSinceSent = (now - new Date(sentAt)) / (1000 * 60 * 60);
  if (hoursSinceSent < escalationHours) return false;
  if (lastReminderAt) {
    const hoursSinceReminder = (now - new Date(lastReminderAt)) / (1000 * 60 * 60);
    if (hoursSinceReminder < cooldownHours) return false;
  }
  return true;
});

return dueForReminder.map(item => ({ json: { ...item.json, config: configItem } }));

